// The TS mirror must agree with crates/mapcheck `check_tables` on every fixture case
// (generated by crates/rules/tests/loot_ts_fixtures.rs).
import { describe, expect, it } from "vitest";
import fixture from "./__fixtures__/loot.json";
import { CHESTS_MAX, CHEST_RADIUS_MAX, CHEST_RADIUS_MIN, NO_TABLE, SETTLE_TIMEOUT_MAX_SECS, SETTLE_TIMEOUT_MIN_SECS, budgetOf, settleDeadline, settleLabel, checkTables, levelsLabel, rewardTables, spentOf, tableAllowed, tierLoot } from "./loot";
import { mockTable } from "./mock";

const tables = rewardTables(mockTable("rewards"));

describe("loot mirror (fixture from crates/rules)", () => {
  it("has the Rust constants", () => {
    expect(NO_TABLE).toBe(fixture.noTable);
    expect(CHESTS_MAX).toBe(fixture.chestsMax);
  });

  it("reads the tier limits like map_rules and tier_limits", () => {
    for (const t of fixture.tiers) {
      expect(tierLoot(t.tier)).toEqual({ chests: t.chests, budget: t.budget, allowed: BigInt(t.allowed), levelCap: t.levelCap });
    }
    expect(tierLoot(0)).toBeNull();
    expect(tierLoot(fixture.tiers.length + 1)).toBeNull();
  });

  it("decodes the registry reward tables", () => {
    expect(tables).toEqual(fixture.tables);
  });

  it("agrees with check_tables on every case", () => {
    for (const c of fixture.cases) {
      expect(checkTables(c.tier, c.minPlayers, c.chests, c.boss, tables), JSON.stringify(c)).toEqual(c.result);
    }
  });
});

describe("loot helpers", () => {
  it("refuses a one-level boss table", () => {
    // The shipped tables all have two levels: flatten an allowed one.
    const tier = fixture.tiers[0]!.tier;
    const boss = tables.find((t) => tableAllowed(t, tier) && t.levelMax > t.levelBase)!;
    const flat = tables.map((t) => (t.id === boss.id ? { ...t, levelMax: t.levelBase } : t));
    expect(checkTables(tier, 1, [], boss.id, flat)).toEqual({ err: "BossTableOneLevel" });
  });

  it("counts the budget and the spent points", () => {
    const t1 = fixture.tiers[0]!;
    expect(budgetOf(t1.tier, 1)).toBe(t1.budget[0]);
    expect(budgetOf(t1.tier, 5)).toBe(0);
    const [a, b] = tables;
    expect(spentOf([a!.id, a!.id], b!.id, tables)).toBe(a!.cost * 2 + b!.cost);
    expect(spentOf([], NO_TABLE, tables)).toBe(0);
  });

  it("patch 11: the deadline is the map's time after the end; the DM's limits come from balance.json", () => {
    expect(settleDeadline(1_000n, 600)).toBe(1_600);
    expect([CHEST_RADIUS_MIN, CHEST_RADIUS_MAX, SETTLE_TIMEOUT_MIN_SECS, SETTLE_TIMEOUT_MAX_SECS]).toEqual([1, 10, 600, 36_000]);
    expect([settleLabel(600), settleLabel(3600), settleLabel(5400)]).toEqual(["10 min", "1 h", "1 h 30 min"]);
  });

  it("labels the level range", () => {
    expect(levelsLabel({ id: 0, levelBase: 1, levelMax: 2, cost: 0 })).toBe("levels 1-2");
    expect(levelsLabel({ id: 0, levelBase: 3, levelMax: 3, cost: 0 })).toBe("level 3");
    expect(levelsLabel(undefined)).toBe("unknown table");
  });
});
